/**
 * Thesaurus lookups from the bundled WordNet-derived data (public/thesaurus/en.json, generated by
 * tools/generate-thesaurus.mjs; see public/thesaurus/README.md for provenance and license). The data
 * is fetched on first use only.
 */

const POS_NAMES = ['noun', 'verb', 'adjective', 'adverb'];

let loading = null;
/** Load the thesaurus once: resolves the parsed data (with a lemma lookup map attached). */
export function loadThesaurus(base = document.baseURI) {
  loading ??= (async () => {
    const response = await fetch(new URL('thesaurus/en.json', base));
    if (!response.ok) throw new Error('The thesaurus could not be loaded.');
    return prepareThesaurus(await response.json());
  })().catch(error => { loading = null; throw error; });
  return loading;
}

/** Attach lookup maps to raw thesaurus data (idempotent). */
export function prepareThesaurus(data) {
  if (data.lemmas) return data;
  const lemmas = new Map();
  data.w.forEach((word, i) => { if (data.x[i]) lemmas.set(word, i); });
  const irregular = new Map();
  for (const [form, base, pos] of data.e || []) { if (!irregular.has(form)) irregular.set(form, []); irregular.get(form).push({ lemma: data.w[base], pos: POS_NAMES[pos] ?? null }); }
  Object.defineProperty(data, 'lemmas', { value: lemmas, enumerable: false });
  Object.defineProperty(data, 'irregular', { value: irregular, enumerable: false });
  return data;
}

/** Base forms a word might be an inflection of, most likely first, as { lemma, pos } (regular English endings). */
export function baseForms(word) {
  const out = [];
  const add = (form, pos) => { if (form && form.length > 1 && form !== word && !out.some(o => o.lemma === form)) out.push({ lemma: form, pos }); };
  const doubled = stem => stem.length > 2 && stem.at(-1) === stem.at(-2) && !/[aeiouyls]/.test(stem.at(-1)) ? stem.slice(0, -1) : null;
  if (word.endsWith('ies') && word.length > 4) add(word.slice(0, -3) + 'y', 'noun');
  if (word.endsWith('ves') && word.length > 4) { add(word.slice(0, -3) + 'f', 'noun'); add(word.slice(0, -3) + 'fe', 'noun'); }
  if (/(?:ches|shes|sses|xes|zes|oes)$/.test(word)) add(word.slice(0, -2), 'noun');
  if (word.endsWith('s') && !word.endsWith('ss')) add(word.slice(0, -1), 'noun');
  for (const [suffix, minimum] of [['ing', 5], ['ed', 4]]) {
    if (!word.endsWith(suffix) || word.length < minimum) continue;
    const stem = word.slice(0, -suffix.length);
    if (suffix === 'ed' && stem.endsWith('i')) add(stem.slice(0, -1) + 'y', 'verb');
    add(doubled(stem), 'verb'); add(stem, 'verb'); add(stem + 'e', 'verb');
  }
  for (const suffix of ['est', 'er']) {
    if (!word.endsWith(suffix) || word.length < suffix.length + 3) continue;
    const stem = word.slice(0, -suffix.length);
    if (stem.endsWith('i')) add(stem.slice(0, -1) + 'y', 'adjective');
    add(doubled(stem), 'adjective'); add(stem, 'adjective'); add(stem + 'e', 'adjective');
  }
  return out;
}

const MAX_SENSES = 8;
function sensesOf(data, lemma, preferred) {
  const index = data.lemmas.get(lemma);
  if (index === undefined) return [];
  const senses = data.x[index].map(id => {
    const [pos, gloss, synonyms, antonyms] = data.s[id];
    const words = list => list.map(i => data.w[i]).filter(w => w.toLowerCase() !== lemma);
    return { pos: POS_NAMES[pos], gloss: data.g[gloss], synonyms: words(synonyms), antonyms: words(antonyms) };
  }).filter(sense => sense.synonyms.length || sense.antonyms.length);
  // An inflected form says which part of speech it is: list those senses first.
  return preferred ? [...senses.filter(s => s.pos === preferred), ...senses.filter(s => s.pos !== preferred)] : senses;
}

/**
 * Look a word up: { word, lemma, senses: [{ pos, gloss, synonyms, antonyms }] } or null.
 * Tries the word itself, then listed irregular forms, then regular inflections. When the word is a
 * lemma of its own and also an inflection (e.g. "improving"), the base form's senses follow.
 */
export function lookupWord(data, word) {
  if (!data || typeof word !== 'string') return null;
  prepareThesaurus(data);
  const key = word.trim().toLowerCase().replace(/[’]/g, "'");
  if (!key) return null;
  const candidates = [{ lemma: key, pos: null }, ...(data.irregular.get(key) || []), ...baseForms(key)];
  let result = null;
  for (const { lemma, pos } of candidates) {
    const senses = sensesOf(data, lemma, pos);
    if (!senses.length) continue;
    if (!result) { result = { word, lemma, senses }; if (lemma !== key) break; continue; }
    if (lemma !== result.lemma) { result.senses.push(...senses.map(s => ({ ...s, lemma }))); break; }
  }
  if (result) result.senses = result.senses.slice(0, MAX_SENSES);
  return result;
}

/** Give `replacement` the capitalization of `source`: UPPER, Title or as listed. */
export function matchCase(source, replacement) {
  if (!source || !replacement) return replacement;
  const letters = source.replace(/[^\p{L}]/gu, '');
  if (letters.length > 1 && letters === letters.toUpperCase()) return replacement.toUpperCase();
  if (letters && letters[0] === letters[0].toUpperCase() && letters[0] !== letters[0].toLowerCase()) return replacement[0].toUpperCase() + replacement.slice(1);
  return replacement;
}
